	protected override void OnSessionEvent(global::Dpr.NetworkUtils.SessionEventData eventData) {
        switch (eventData.eventType)
        {
            case SessionEventType.JoinIn_Mine:
                JoinMine(eventData.stationIndex);
                break;
            case SessionEventType.JoinIn_OtherPlayer:
                JoinOtherPlayer(eventData.stationIndex);
                break;
            case SessionEventType.Leave_OtherPlayer:
                LeaveOtherPlayer(eventData.stationIndex);
                break;
            case SessionEventType.GamingError:
            case SessionEventType.Crash:
            case SessionEventType.ResumeGame:
                NetworkError();
                break;
        }
    }
	private void JoinMine(int stationIndex) {
        ResetNetworkDataByStationIndex(stationIndex);
    }
	private void JoinOtherPlayer(int stationIndex) {
        ResetNetworkDataByStationIndex(stationIndex);
        SendJoinData(stationIndex);
        SendRequestData(stationIndex, NetDataColiseumReadyPointJoinData.DataID);
    }
	private void LeaveOtherPlayer(int stationIndex) {
        int pointIndex = playerReadyPointIndexArray[stationIndex];
        if (pointIndex >= 0 && pointIndex < battleReadyPoints.Count)
        {
            BattleReadyPoint readyPoint = GetReadyPoint(pointIndex);
            if (readyPoint != null)
            {
                readyPoint.Leave();
                readyPoint.PlayWaitEffect();
            }
        }

        ResetNetworkDataByStationIndex(stationIndex);
        _OpcManager.RemoveCharacter(stationIndex, true);
        if (battleMatchingManager != null && !battleMatchingManager.IsStateBattle)
            battleMatchingManager.LeaveOther(stationIndex);
    }
	private void NetworkError() {
        if (isNetworkError)
            return;

        EmitLog("NETWORK_ERROR!!");
        if (coliseumState == ColiseumState.LEAVE)
        {
            EmitLog("CurrentState is LEAVE");
            return;
        }

        isNetworkError = true;
        DisableNPCTalk();
        if (coliseumFrontController != null)
        {
            coliseumFrontController.isTalkEnd = true;
            coliseumFrontController.Clear();
        }

        PlayerWork.isPlayerInputActive = false;
        Destroy(startPointObject);
        startPointObject = null;
        if (!playerMove.IsStateNone)
            playerMove.StopPlayerMove();

        playerMove.StopControlPlayer(true);
        if (battleMatchingManager.IsStateBattle)
            return;

        if (!battleMatchingManager.IsStateNone)
            battleMatchingManager.OnError();

        if (battleMatchingManager != null)
            NetworkManager.ShowApplicationErrorDialog(ErrorCodeID.ErrorDisconnectionSession, res => LeaveColiseum());

        ChangeState(ColiseumState.ERROR);
    }
