	private void LoadReadyPointEffect(global::EffectFieldID effectID, global::System.Action onFinished) {
        Sequencer.Start(Utils.LoadEffect(effectID, e =>
        {
            EmitLog(string.Format("Load Finish : [{0}]", effectID));
            if (effectDataTable.ContainsKey((int)effectID))
                EmitLog(string.Format("Already Loaded Effect : [{0}]", effectID));
            else
                effectDataTable.Add((int)effectID, e);

            onFinished?.Invoke();
        }));
    }
	private void SetUp() {
        SwitchNotification.SetFocusHandlingModeNotify();
        float y = player.worldPosition.y;
        Vector3 pos = new Vector3(UnionWork.startPosColiseum.x, y, UnionWork.startPosColiseum.z);
        player.SetPositionDirect(pos);
        CreateWarpCollision();
        sessionManager.OnErrorSession = NetworkError;
        sessionManager.StartSession(matchingParam);
        InitNetData();
        reserveReadyPointIndex = -1;
        fixedReadyPointIndex = -1;
        isEnableInput = true;
        isCalledFadeOut = false;
        isNetworkError = false;
        playerMove = new ColiseumPlayerMove();
        playerMove.Initialize(player);
        battleMatchingManager = new BattleMatchingManager();
        battleMatchingManager.Initialize(ReturnBattleMatching);
        myPlayer._myAnimationPlayer = player.GetAnimationPlayer();
        if (showMsgWindow == null)
        {
            showMsgWindow = new ShowMessageWindow();
            showMsgWindow.Setup("ss_box", PlayerWork.config.msg_speed, true);
            showMsgWindow.ShowMessage(UnionTextData.UNION_WAIT_SS_GAMING_MESSAGE);
        }

        ChangeState(ColiseumState.FREE_MOVE);
        waitInitCoroutine = Sequencer.Start(UnionWork.WaitNetworkSessionStateGaming(null, null, () =>
        {
            if (showMsgWindow != null)
            {
                showMsgWindow.CloseMsgWindow();
                showMsgWindow.ChangeMSBTFile("ss_net_net_btl");
            }

            SetUpColiseum();
            if (frontDeskEntity != null)
                frontDeskEntity.EventParams.TalkBit = NPC_TALK_BIT;
        }, NetworkError));
    }
	private void CreateWarpCollision() {
        startPointObject = new GameObject(WARP_OBJ_NAME);
        startPointObject.transform.position = UnionWork.startPosColiseum;
        pointCollision = startPointObject.AddComponent<UnionStartPointCollision>();
        pointCollision.Init();
        pointCollision.Create(LeaveColiseum, 0.01f, player.gameObject);
        pointCollision.isLandStartPoint = true;
    }
	private void CreateFrontDesk() {
        fdControllerObject = new GameObject(FRONT_DESK_CONTROLLER);
        coliseumFrontController = fdControllerObject.AddComponent<ColiseumFrontDeskStateController>();
        coliseumFrontController.isTalkEnd = true;
        coliseumFrontController.Init();
        if (frontDeskEntity != null)
            return;

        foreach (FieldCharacterEntity character in EntityManager.fieldCharacters)
        {
            if (character.name.Equals(NPC_OBJ_NAME))
            {
                frontDeskEntity = character.gameObject.GetComponentNullable<FieldCharacterEntity>();
                frontDeskEntity.EventParams.TalkBit = NPC_TALK_BIT;
            }
        }

        if (frontDeskEntity == null)
            EmitLog("[" + NPC_OBJ_NAME + "] not found!!");
    }
	private void SetUpColiseum() {
        int playerNumMax = NetworkManager.NetworkParam.playerNumMax;
        for (int i = 0; i < playerNumMax; i++)
        {
            GameObject obj = new GameObject("ReadyPoint" + i);
            BattleReadyPoint readyPoint = obj.AddComponent<BattleReadyPoint>();
            SetBattleReadyPos(i, obj);
            EffectFieldID waitEffectID = i % 2 == 0 ? EffectFieldID.EF_F_MARK_SQUARE_BLUE_01 : EffectFieldID.EF_F_MARK_SQUARE_RED_01;
            EffectFieldID readyEffectID = i % 2 == 0 ? EffectFieldID.EF_F_MARK_SQUARE_BLUE_02 : EffectFieldID.EF_F_MARK_SQUARE_RED_02;
            readyPoint.Create(i, 1.0f, player.gameObject, effectDataTable[(int)waitEffectID], effectDataTable[(int)readyEffectID]);
            readyPoint.PlayWaitEffect();
            battleReadyPoints.Add(readyPoint);
        }
    }
	private void SetBattleReadyPos(int index, global::UnityEngine.GameObject obj) {
        if (obj == null)
            return;

        float x = UnionWork.GetReadyPosX(index);
        float z = UnionWork.GetReadyPosZ(index);
        obj.transform.position = new Vector3(x, 0.0f, z);
    }
