        }

        if (pointCollision != null)
            pointCollision = null;

        if (startPointObject != null)
        {
            Destroy(startPointObject);
            startPointObject = null;
        }

        if (frontDeskEntity != null)
            frontDeskEntity = null;

        if (battleReadyPoints != null)
        {
            int count = battleReadyPoints.Count;
            for (int i = 0; i < count; i++)
            {
                BattleReadyPoint readyPoint = battleReadyPoints[i];
                if (readyPoint != null)
                    Destroy(readyPoint.gameObject);
            }

            battleReadyPoints = null;
        }

        if (playerMove != null)
        {
            playerMove.OnFinalize();
            playerMove = null;
        }

        if (showMsgWindow != null)
        {
            showMsgWindow.OnFinalize();
            showMsgWindow = null;
        }

        SwitchNotification.SetFocusHandlingModeSuspend();
    }
	public override void SetMatchingParam(global::Dpr.SubContents.MatchingParam matchingParam) {
        this.matchingParam = matchingParam;
    }
	public void SetZoneData(global::ZoneID zoneId, int locIndex, global::UnityEngine.Vector2Int gridPos) {
        EmitLog(string.Format("Set Return ZoneID : [{0}]", zoneId));
        returnZoneID = zoneId;
    }
	public void SetBattleRule(global::Dpr.NetworkUtils.BattleModeID ruleId) {
        battleModeID = ruleId;
        EmitLog(string.Format("Set BattleMode : [{0}]", ruleId));
    }
	protected override void MyUpdate(float deltaTime) {
        switch (coliseumState)
        {
            case ColiseumState.FREE_MOVE:
                UpdateStateFREE_MOVE();
                break;
            case ColiseumState.CHECK_CAN_ENTRY:
                UpdateCHECK_CAN_ENTRY();
                break;
            case ColiseumState.WAIT_ENTRY_OTHER:
                UpdateWAIT_ENTRY_OTHER();
                break;
            case ColiseumState.WAIT_START_MATCHING:
                UpdateWAIT_START_MATCHING();
                break;
            case ColiseumState.LEAVE:
                UpdateLEAVE();
                break;
        }

        if (isNetworkError)
            return;

        UpdateControlPlayer(deltaTime);
        SendPosData();
        UpdateNetwork();
    }
	private void UpdateStateFREE_MOVE() {
        if (IsNullReadyPoint())
            return;

        if (!CheckContactReadyPoint(out int contactIndex))
            return;

        EmitLog(string.Format("Contact ReadyPoint[{0}]", contactIndex));
        reserveReadyPointIndex = contactIndex;
        if (!networkManager.IsJoinOtherPlayer())
        {
            EntryReadyPoint();
            return;
        }

        SendConfirmEntryTeam(contactIndex);
        ChangeState(ColiseumState.CHECK_CAN_ENTRY);
    }
	private bool CheckContactReadyPoint(out int contactIndex) {
        contactIndex = -1;
        float minDistance = 0.0f;
        foreach (BattleReadyPoint readyPoint in battleReadyPoints)
        {
            if (!readyPoint.IsContact())
                continue;

            float distance = Vector3.Distance(readyPoint.transform.position, player.transform.position);
            if (distance <= minDistance || contactIndex < 0)
            {
                contactIndex = readyPoint.PointNumber;
                minDistance = distance;
            }
        }

        if (contactIndex >= 0 && battleReadyPoints[contactIndex].IsEnter)
            contactIndex = -1;

        return contactIndex >= 0;
    }
	private void UpdateCHECK_CAN_ENTRY() {
        bool canEntry = true;
        for (int i = 0; i < sendedPlayerFlagArray.Length; i++)
        {
            if (!sendedPlayerFlagArray[i] || !networkManager.IsGamerActive(i))
                continue;

            AnswerID answer = receivedAnswerArray[i];
            if (answer == AnswerID.NG)
                canEntry = false;
            else if (answer == AnswerID.NONE)
                return;
        }

        EmitLog(string.Format("canEntry [{0}] : [{1}]", canEntry, reserveReadyPointIndex));
        ResetCheckEnterReadyPointData();
        if (canEntry)
        {
            EntryReadyPoint();
            return;
        }

        if (reserveReadyPointIndex >= 0)
            battleReadyPoints[reserveReadyPointIndex].Enter();

        ChangeState(ColiseumState.FREE_MOVE);
    }
	private void EntryReadyPoint() {
        if (reserveReadyPointIndex < 0)
            return;

        BattleReadyPoint readyPoint = battleReadyPoints[reserveReadyPointIndex];
        MovePlayerToReadyPoint(readyPoint.PointNumber);
        readyPoint.Enter();
        EmitLog(string.Format("Entry ReadyPoint[{0}]", reserveReadyPointIndex));
    }
	private void MovePlayerToReadyPoint(int hitColNum) {
        if (player == null || battleReadyPoints == null)
            return;

        if (battleReadyPoints[hitColNum] == null)
            return;

        ChangeState(ColiseumState.WAIT_ENTRY_OTHER);
        fixedReadyPointIndex = hitColNum;
        BattleReadyPoint readyPoint = battleReadyPoints[hitColNum];
        readyPoint.Leave();
        isEnableInput = false;
        playerMove.StartMoveToPoint(readyPoint.transform.position, hitColNum);
        EmitLog(string.Format("Start Move to Point[{0}]", hitColNum));
    }
	private bool IsNullReadyPoint() {
        return battleReadyPoints.IsNullOrEmpty();
    }
	private global::BattleReadyPoint GetReadyPoint(int index) {
        if (IsNullReadyPoint() || index < 0 || index >= battleReadyPoints.Count)
            return null;

        return battleReadyPoints[index];
    }
	private void UpdateWAIT_ENTRY_OTHER() {
        if (!isEnableInput)
            return;

        if (Utils.PushB && battleMatchingManager.IsStateNone)
        {
            AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_CANCEL);
            LeavePlayerFromReadyPoint();
        }

        if (!NetworkManager.IsHost)
            return;

        if (!CheckAllPlayerReadyOk() || !CheckAllPlayerPointOK())
            return;

        isEnableInput = false;
        BattleStart();
        SendRequestDataToAll(NetDataTransitionData.DataID);
    }
	private void LeavePlayerFromReadyPoint() {
        if (player == null || battleReadyPoints == null)
            return;

        if (battleReadyPoints[fixedReadyPointIndex] == null)
            return;

        if (coliseumState != ColiseumState.BATTLE && coliseumState != ColiseumState.WAIT_ENTRY_OTHER)
            return;

        ChangeState(ColiseumState.FREE_MOVE);
        LeavePoint(fixedReadyPointIndex, IlcaNetSession.ThisStationIndex());
        Vector3 pointPosition = battleReadyPoints[fixedReadyPointIndex].transform.position;
        showMsgWindow.CloseMsgWindow();
        isEnableInput = false;
        float offsetX = fixedReadyPointIndex % 2 == 0 ? 2.0f : -2.0f;
        Vector3 goalPosition = new Vector3(pointPosition.x + offsetX, 0.0f, player.worldPosition.z);
        playerMove.StartLeaveFromPoint(goalPosition);
        EmitLog("LeaveControllPlayer");
    }
	private void BattleStart() {
        ResetReadyData();
        if (battleMatchingManager != null)
        {
            battleMatchingManager.ColiseumLeavePoint = -1;
            battleMatchingManager.ResetData();
        }

        if (coliseumState != ColiseumState.WAIT_ENTRY_OTHER)
            return;

        EmitLog("[Coliseum]BattleStart");
        playerMove.StopControlPlayer(false);
        isEnableInput = false;
        showMsgWindow.ShowAutoCloseMessage(UnionTextData.COLISEUM_BATTLE_START, 2.0f);
        isCalledFadeOut = false;
        ChangeState(ColiseumState.WAIT_START_MATCHING);
    }
	private void UpdateWAIT_START_MATCHING() {
        if (showMsgWindow.IsOpen)
            return;

        if (!isCalledFadeOut)
        {
            isCalledFadeOut = true;
            Fader.FadeOut(FADE_OUT_DURATION);
            return;
        }

        if (Fader.isBusy)
            return;

        BattleMatchingWork.networkType = NetworkManager.NetworkParam.networkType;
        BattleMatchingWork.battleModeID = battleModeID;
        BattleMatchingWork.hostStationIndex = GetHostStationIndex();
        BattleMatchingWork.isColiseum = true;
        BattleMatchingWork.coliseumTeam = fixedReadyPointIndex;
        if (battleModeID == BattleModeID.Multi)
        {
            switch (fixedReadyPointIndex)
            {
                case 0:
                    BattleMatchingWork.coliseumTeam = 0;
                    break;
                case 1:
                    BattleMatchingWork.coliseumTeam = 3;
                    break;
                case 2:
                    BattleMatchingWork.coliseumTeam = 1;
                    break;
                case 3:
                    BattleMatchingWork.coliseumTeam = 2;
                    break;
            }
        }

        EmitLog(string.Format("Set ColiseumTeam [{0}]", fixedReadyPointIndex));
        battleMatchingManager.StartProcess();
        isCalledFadeOut = false;
        ChangeState(ColiseumState.BATTLE);
    }
	private void UpdateLEAVE() {
        if (!CanLeave())
            return;

        EmitLog("Finish Coliseum");
        PlayerWork.SetTransitionZone(returnZoneID, 1);
        EvDataManager.Instanse.SetWork((int)EvWork.WORK_INDEX.UNION_TEMP0, LEAVED_COLISEUM_WORK_VAL);
        ChangeState(ColiseumState.END);
    }
	private bool CanLeave() {
        if (NetworkManager.IsConnect || NetworkManager.IsShowApplicationErrorDialog() || showMsgWindow.IsOpen)
            return false;
        return true;
    }
	private void UpdateControlPlayer(float deltaTime) {
        if (playerMove == null || playerMove.IsStateNone)
            return;

        playerMove.OnUpdate(deltaTime);
        if (playerMove.IsStateFinishArrive)
        {
            EmitLog("Finish PlayerMove Arrive");
            OnReadyWait();
        }
        else if (playerMove.IsStateFinishLeave)
        {
            EmitLog("Finish PlayerMove Leave");
            OnLeaveEnd();
        }
    }
	private void OnReadyWait() {
        showMsgWindow.ShowMessage(UnionTextData.COLISEUM_MATCH_WAITING);
        BattleReadyPoint readyPoint = battleReadyPoints[fixedReadyPointIndex];
        readyPoint.PlayReadyEffect();
        readyPoint.Enter();
        EntryPoint(fixedReadyPointIndex, IlcaNetSession.ThisStationIndex());
        isEnableInput = true;
        SendStandbyPointData(false);
    }
	private void OnLeaveEnd() {
        if (isNetworkError)
            return;

        isEnableInput = true;
        if (battleReadyPoints[fixedReadyPointIndex] == null)
            return;

        BattleReadyPoint readyPoint = battleReadyPoints[fixedReadyPointIndex];
        if (readyPoint != null)
        {
            int stationIndex = IlcaNetSession.ThisStationIndex();
            bool isOtherPlayerEntry = false;
            if (!playerReadyPointIndexArray.IsNullOrEmpty())
            {
                for (int i = 0; i < playerReadyPointIndexArray.Length; i++)
                {
                    if (i == stationIndex)
                        continue;

                    if (playerReadyPointIndexArray[i] == fixedReadyPointIndex)
                    {
                        isOtherPlayerEntry = true;
                        break;
                    }
                }
            }

            if (!isOtherPlayerEntry)
            {
                readyPoint.Leave();
                readyPoint.PlayWaitEffect();
            }
        }

        SendStandbyPointData(true);
        reserveReadyPointIndex = -1;
        fixedReadyPointIndex = -1;
    }
	private void EntryPoint(int pointIndex, int stationIndex) {
        EntryPointMember(pointIndex, stationIndex);
    }
	private void LeavePoint(int pointIndex, int stationIndex) {
        LeavePointMember(pointIndex, stationIndex);
        if ((coliseumState == ColiseumState.WAIT_START_MATCHING || coliseumState == ColiseumState.BATTLE) && battleMatchingManager != null)
            battleMatchingManager.ColiseumLeavePoint = stationIndex;
    }
	private void DisableNPCTalk() {
        if (frontDeskEntity == null)
        {
            EmitLog("frontDeskEntity is null");
            return;
        }

        frontDeskEntity.EventParams.TalkBit = 0;
    }
	private void LeaveColiseum() {
        if (coliseumState == ColiseumState.LEAVE)
            return;

        EmitLog("Call LeaveColiseum");
        UnionWork.isGaming = false;
        PlayerWork.isPlayerInputActive = false;
        if (waitInitCoroutine != null)
        {
            Sequencer.Stop(waitInitCoroutine);
            waitInitCoroutine = null;
        }

        DisableNPCTalk();
        ChangeState(ColiseumState.LEAVE);
        sessionManager.Clear();
        showMsgWindow.CloseMsgWindow();
        ContextMenuWindow contextMenu = UIManager.Instance.GetExistWindow<ContextMenuWindow>();
        if (contextMenu != null && !contextMenu.IsClosing)
            contextMenu.Close(null);

        if (coliseumFrontController != null)
        {
            coliseumFrontController.isTalkEnd = true;
            coliseumFrontController.Clear();
        }

        PlayerWork.isPlayerInputActive = false;
        if (returnZoneID == ZoneID.C01)
            returnZoneID = ZoneID.C01PC0102;

        myPlayer.isMenuOpen = false;
        ChangeState(ColiseumState.LEAVE);
    }
	public void ReturnBattle() {
        EmitLog("Call ReturnBattle");
        if (BattleMatchingWork.battleResult == BtlResult.BTL_RESULT_COMM_ERROR)
        {
            EmitLog(string.Format("ReturnBattle : BattleResult [{0}]", BattleMatchingWork.battleResult));
            battleMatchingManager.ReturnBattleError();
            if (NetworkManager.IsDisconnected || isNetworkError)
            {
                EmitLog("ReturnBattle : IsDisconnected");
                LeaveColiseum();
                return;
            }

            EmitLog("ReturnBattle : Leave Room");
            AudioManager.Instance.SetBgmEvent(AK.EVENTS.BA_END, false);
            ReturnBattleMatching();
            return;
        }

        if (isNetworkError)
        {
            EmitLog("ReturnBattle : isError");
            AudioManager.Instance.SetBgmEvent(AK.EVENTS.BA_END, false);
            isNetworkError = false;
            battleMatchingManager.ReturnBattleError();
            NetworkError();
            return;
        }

        EmitLog("ReturnBattle : OpenMatching");
        battleMatchingManager.ReturnBattle();
    }
	private void ReturnBattleMatching() {
        EmitLog("Call ReturnBattleMatching");
        if (battleReadyPoints != null)
        {
            foreach (BattleReadyPoint readyPoint in battleReadyPoints)
            {
                if (readyPoint == null)
                    continue;

                if (readyPoint.IsEnter)
                    readyPoint.PlayReadyEffect();
                else
                    readyPoint.PlayWaitEffect();
            }
        }

        if (!isNetworkError)
            LeavePlayerFromReadyPoint();
    }
	private void ChangeState(global::ColiseumRoomManager.ColiseumState nextState) {
        if (coliseumState == nextState)
        {
            EmitLog(string.Format("Can not Change State To : [{0}]. Because Same State", nextState));
            return;
        }

        if (coliseumState == ColiseumState.ERROR && nextState != ColiseumState.LEAVE)
        {
            EmitLog(string.Format("Change State To : [{0}]. Because Now State is Error", nextState));
            return;
        }

        coliseumState = nextState;
        EmitLog(string.Format("Change State : [{0}]", nextState));
        switch (coliseumState)
        {
            case ColiseumState.FREE_MOVE:
                playerMove.StartControlPlayer();
                break;
            case ColiseumState.CHECK_CAN_ENTRY:
                playerMove.StopControlPlayer(true);
                break;
        }
    }
	public static void EmitLog(string log, global::UnityEngine.LogType logType = (global::UnityEngine.LogType)(3)) {
        // Empty in the binary (018e5200): every call site's string work is still evaluated.
    }
	public ColiseumRoomManager() { }
	static ColiseumRoomManager() { }
	public enum ColiseumState
	{
		INIT = 0,
		FREE_MOVE = 1,
		CHECK_CAN_ENTRY = 2,
		WAIT_ENTRY_OTHER = 3,
		WAIT_START_MATCHING = 4,
		BATTLE = 5,
		LEAVE = 6,
		END = 7,
		ERROR = 8,
	}
	private enum AnswerID
	{
		NG = 0,
		OK = 1,
		NONE = 2,
	}
}
